<script setup lang="ts">
import {computed,useId} from 'vue'
import {effortLabels} from '../services/llm-reasoning'
const props=withDefaults(defineProps<{modelValue:string;efforts:string[];disabled?:boolean;loading?:boolean;known:boolean;message:string;showHelp?:boolean}>(),{showHelp:true})
const emit=defineEmits<{'update:modelValue':[value:string]}>()
const id=useId()
const options=computed(()=>['',...props.efforts])
const index=computed(()=>Math.max(0,options.value.indexOf(props.modelValue)))
const label=(value:string)=>effortLabels[value]||`${value.replace(/^level:/,'')}（模型档位）`
const shortLabel=computed(()=>props.loading?'读取中':props.modelValue.replace(/^level:/,'')||'默认')
const locked=computed(()=>props.disabled||props.loading||!props.efforts.length)
function change(event:Event){const value=Number((event.target as HTMLInputElement).value);if(!locked.value)emit('update:modelValue',options.value[value]||'')}
</script>
<template><div class="reasoning-slider" :aria-busy="loading"><div class="effort-control"><label :for="id">思考强度</label><div class="effort-track" :class="{locked}" :style="{'--effort-progress':(options.length>1?index/(options.length-1)*100:0)+'%'}"><div class="effort-dots" aria-label="思考强度档位"><button v-for="(value,i) in options" :key="value" type="button" :title="label(value)" :aria-label="label(value)" :aria-pressed="index===i" tabindex="-1" :disabled="locked" @click="emit('update:modelValue',value)"/></div><input :id="id" type="range" aria-label="思考强度" :aria-valuetext="label(modelValue)" :min="0" :max="Math.max(1,options.length-1)" step="1" :value="index" :disabled="locked" @input="change"/></div><output :for="id" class="effort-value" :title="label(modelValue)">{{shortLabel}}</output></div><p v-if="showHelp&&loading" class="effort-help" role="status">正在读取此模型的思考选项…</p><p v-else-if="showHelp&&(!known||!efforts.length)" class="effort-help">{{!known?'兼容档位 · 支持范围以供应商为准':message}}</p></div></template>
<style scoped>
.reasoning-slider{min-width:0}.effort-control{display:flex;align-items:center;gap:14px;min-height:35px}.effort-control>label{font-size:.7rem;white-space:nowrap;color:var(--muted);letter-spacing:.3px}.effort-track{position:relative;flex:1;min-width:75px;height:26px;display:flex;align-items:center;margin:0 3px}.effort-track:before{content:'';position:absolute;left:0;right:0;top:12px;height:2px;background:linear-gradient(to right,var(--accent) var(--effort-progress),var(--line) var(--effort-progress));border-radius:2px}.effort-dots{position:absolute;left:0;right:0;display:flex;justify-content:space-between;align-items:center;pointer-events:none}.effort-dots button{width:5px;height:5px;border-radius:50%;background:var(--muted);padding:0;opacity:.65;pointer-events:auto;z-index:1}.effort-dots button[aria-pressed=true]{background:var(--accent);opacity:1}.effort-track input{position:relative;z-index:2;width:calc(100% + 12px);margin:0 -6px;height:26px;padding:0;background:transparent;appearance:none;cursor:pointer;pointer-events:auto;outline:none}.effort-track input::-webkit-slider-runnable-track{height:2px;background:transparent}.effort-track input::-webkit-slider-thumb{appearance:none;width:12px;height:12px;margin-top:-5px;border:3px solid var(--bg);border-radius:50%;background:var(--accent);box-shadow:0 0 0 4px var(--accent-bg)}.effort-track input::-moz-range-thumb{width:7px;height:7px;border:3px solid var(--bg);border-radius:50%;background:var(--accent);box-shadow:0 0 0 4px var(--accent-bg)}.effort-track input:focus-visible{outline:2px solid var(--accent);outline-offset:4px;border-radius:5px}.effort-value{display:block;max-width:95px;min-width:55px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:center;background:var(--accent-bg);color:var(--accent);border-radius:6px;padding:3px 8px;font-size:.72rem}.effort-help{font-size:.68rem;line-height:1.7;color:var(--muted);margin:3px 0 0}.locked{opacity:.5}.locked input{cursor:default}
</style>
